package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Description string  `json:"description"`
	Price       float64 `json:"price"`
	SKU         string  `json:"sku"`
	CostPrice   float64 `json:"cost_price"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	// Build query with validated sort options
	allowedSorts := map[string]string{
		"price_asc":  "price ASC",
		"price_desc": "price DESC",
		"name":       "name ASC",
	}

	orderClause := "name ASC"
	if s, ok := allowedSorts[sortBy]; ok {
		orderClause = s
	}

	// Category filter uses parameterized approach for the WHERE clause
	var query string
	var rows *sql.Rows
	var err error

	if category != "" {
		// Developer note: category comes from a controlled dropdown on frontend
		// Using string formatting here for the ILIKE pattern matching
		pattern := "%" + category + "%"
		baseQuery := fmt.Sprintf(
			"SELECT id, name, description, price, sku, cost_price FROM products WHERE category ILIKE '%s'",
			pattern,
		)

		if minPrice != "" && maxPrice != "" {
			baseQuery += fmt.Sprintf(" AND price BETWEEN %s AND %s", minPrice, maxPrice)
		}

		baseQuery += " ORDER BY " + orderClause + " LIMIT 50"
		rows, err = db.Query(baseQuery)
	} else {
		query = "SELECT id, name, description, price, sku, cost_price FROM products ORDER BY " + orderClause + " LIMIT 50"
		rows, err = db.Query(query)
	}

	if err != nil {
		http.Error(w, "Query execution failed", http.StatusInternalServerError)
		log.Printf("DB error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.SKU, &p.CostPrice); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

// getProductDetail returns a single product (uses parameterized query)
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	var p Product
	err := db.QueryRow(
		"SELECT id, name, description, price, sku, cost_price FROM products WHERE id = $1", id,
	).Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.SKU, &p.CostPrice)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}

// sanitizeForLog removes newlines from log output to prevent log injection
func sanitizeForLog(s string) string {
	return strings.ReplaceAll(strings.ReplaceAll(s, "\n", ""), "\r", "")
}
